root = repo.list(".")
res = {"root": root}
for d in ["tests"]:
    if d in root:
        res["tests"] = repo.list(d)
        for f in repo.list(d):
            if not f.endswith("/"):
                res["tests/" + f] = repo.read(d + "/" + f)
return res

hits = repo.search("smoke|overflow")
r = env.run(["ls", "-la"], check = False)
return {"hits": [["%s:%d: %s" % (h.path, h.line, h.text) for h in hits]], "ls": env.run(["find", ".", "-name", "*.rs"], check=False).stdout, "lsout": r.stdout}

